<script lang="ts">import { MasonryItem,MasonryRoot,MasonryViewport } from '@fex-design/svelte/primitive/masonry';import Button from '@fex-design/svelte/ui/button';import { masonryItems } from './data';const summaries=['待确认需求范围','正在整理交互状态','已完成视觉走查','等待接口数据','正在补充异常分支','已进入回归验证','准备发布说明','等待最终确认'],details=['补充响应式宽度变化后的验收结果。','记录图片加载完成后的重新测量过程。','确认动态内容不会覆盖相邻项目。'],items=masonryItems.slice(0,8);let target=$state(0),detailCount=$state(0);const switchTarget=()=>{target=(target+1)%items.length;detailCount=0}</script>
<div class="grid gap-space-md"><div class="flex flex-wrap items-center gap-space-sm rounded-md border border-border bg-muted-background p-space-sm"><span class="mr-auto text-sm">当前观察：<strong>Card {target+1}</strong> · 新增 {detailCount} 段</span><Button size="sm" variant="outline" onclick={switchTarget}>切换目标</Button><Button size="sm" onclick={()=>detailCount=Math.min(details.length,detailCount+1)}>追加内容</Button><Button size="sm" variant="outline" disabled={!detailCount} onclick={()=>detailCount=Math.max(0,detailCount-1)}>收起内容</Button><Button size="sm" variant="outline" onclick={()=>detailCount=details.length}>连续更新</Button><Button size="sm" variant="ghost" onclick={()=>detailCount=0}>重置</Button></div><MasonryRoot columns={{minColumnWidth:220,max:4}} gap={16}><MasonryViewport>{#each items as item,index(item.id)}{@const active=index===target}<MasonryItem itemKey={item.id} {index}><article class={`grid gap-space-sm rounded-md border p-space-md ${active?'border-primary bg-primary/5':'border-border bg-background'}`}><div class="flex items-center justify-between gap-space-sm"><strong>{item.title}</strong><span class="rounded-full bg-muted px-2 py-0.5 text-xs text-muted-foreground">{active?'观察中':`第 ${index+1} 项`}</span></div><p class="text-sm text-muted-foreground">{summaries[index]}</p>{#if active}{#each details.slice(0,detailCount) as detail(detail)}<p class="border-t border-border pt-space-sm text-sm">{detail}</p>{/each}{/if}</article></MasonryItem>{/each}</MasonryViewport></MasonryRoot></div>
